    size_t out_len = WebPEncodeRGBA(rgba, w, h, w * 4, 80.0f, &out_ptr);
    printf("Encoded WebP in C at q=80: %zu bytes\n", out_len);

    WebPFree(rgba);
    WebPFree(out_ptr);
    free(buf);
    return 0;
}
