{"command":"cat <<'EOF' > /tmp/test_png.c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct png_struct_def png_struct;
typedef struct png_info_def png_info;
typedef png_struct* png_structp;
typedef png_info* png_infop;
typedef const png_struct* png_const_structp;
typedef const png_info* png_const_infop;

typedef void (*png_rw_ptr)(png_structp, uint8_t*, size_t);

extern png_structp png_create_read_struct(const char* ver, void* err, void* err_fn, void* warn_fn);
extern png_infop png_create_info_struct(png_const_structp png_ptr);
extern void png_destroy_read_struct(png_structp* png_ptr, png_infop* info, png_infop* end_info);
extern void png_set_read_fn(png_structp png_ptr, void* io_ptr, png_rw_ptr read_data_fn);
extern void png_read_info(png_structp png_ptr, png_infop info_ptr);
extern uint32_t png_get_image_width(png_const_structp png_ptr, png_const_infop info_ptr);
extern uint32_t png_get_image_height(png_const_structp png_ptr, png_const_infop info_ptr);
extern uint8_t png_get_color_type(png_const_structp png_ptr, png_const_infop info_ptr);
extern uint8_t png_get_bit_depth(png_const_structp png_ptr, png_const_infop info_ptr);
extern void png_set_palette_to_rgb(png_structp png_ptr);
extern void png_set_expand_gray_1_2_4_to_8(png_structp png_ptr);
extern void png_set_tRNS_to_alpha(png_structp png_ptr);
extern void png_set_filler(png_structp png_ptr, uint32_t filler, int flags);
extern void png_read_update_info(png_structp png_ptr, png_infop info_ptr);
extern void png_read_image(png_structp png_ptr, uint8_t** image);

extern png_structp png_create_write_struct(const char* ver, void* err, void* err_fn, void* warn_fn);
extern void png_destroy_write_struct(png_structp* png_ptr, png_infop* info);
extern void png_set_write_fn(png_structp png_ptr, void* io_ptr, png_rw_ptr write_data_fn, void* flush_fn);
extern void png_set_IHDR(png_const_structp png_ptr, png_infop info_ptr, uint32_t width, uint32_t height, int bit_depth, int color_type, int interlace_method, int compression_method, int filter_method);
extern void png_write_info(png_structp png_ptr, png_infop info_ptr);
extern void png_write_image(png_structp png_ptr, uint8_t** image);
extern void png_write_end(png_structp png_ptr, png_infop info_ptr);
extern void png_set_compression_level(png_structp png_ptr, int level);

typedef struct {
    const uint8_t* data;
    size_t size;
    size_t offset;
} MemReader;

static void user_read_data(png_structp png_ptr, uint8_t* out_bytes, size_t length) {
    MemReader* reader = (MemReader*)png_ptr; // standard libpng io_ptr is retrieved via png_get_io_ptr
    // but in libpng png_get_io_ptr(png_ptr) returns io_ptr
}

extern void* png_get_io_ptr(png_const_structp png_ptr);

static void user_read_fn(png_structp png_ptr, uint8_t* out_bytes, size_t length) {
    MemReader* r = (MemReader*)png_get_io_ptr(png_ptr);
    if (r->offset + length <= r->size) {
        memcpy(out_bytes, r->data + r->offset, length);
        r->offset += length;
    }
}

typedef struct {
    uint8_t* data;
    size_t size;
    size_t cap;
} MemWriter;

static void user_write_fn(png_structp png_ptr, uint8_t* in_bytes, size_t length) {
    MemWriter* w = (MemWriter*)png_get_io_ptr(png_ptr);
    if (w->size + length > w->cap) {
        w->cap = (w->size + length) * 2 + 1024;
        w->data = realloc(w->data, w->cap);
    }
    memcpy(w->data + w->size, in_bytes, length);
    w->size += length;
}

static void user_flush_fn(png_structp png_ptr) {}

int main() {
    FILE* f = fopen("assets/p0.png", "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    size_t len = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* buf = malloc(len);
    fread(buf, 1, len, f);
    fclose(f);

    MemReader reader = {buf, len, 0};
    png_structp png_ptr = png_create_read_struct("1.6.37", NULL, NULL, NULL);
    png_infop info_ptr = png_create_info_struct(png_ptr);

    png_set_read_fn(png_ptr, &reader, user_read_fn);
    png_read_info(png_ptr, info_ptr);

    uint32_t w = png_get_image_width(png_ptr, info_ptr);
    uint32_t h = png_get_image_height(png_ptr, info_ptr);
    uint8_t color_type = png_get_color_type(png_ptr, info_ptr);
    uint8_t bit_depth = png_get_bit_depth(png_ptr, info_ptr);

    printf("PNG %u x %d, color_type=%d, bit_depth=%d\n", w, h, color_type, bit_depth);

    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
    free(buf);
    return 0;
}
EOF
