    *h = cinfo.output_height;

    uint8_t* rgb = malloc((*w) * (*h) * 3);
    uint8_t* row_ptrs[1];

    while (cinfo.output_scanline < cinfo.output_height) {
        row_ptrs[0] = rgb + cinfo.output_scanline * (*w) * 3;
        jpeg_read_scanlines(&cinfo, row_ptrs, 1);
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    // Convert RGB to RGBA
    uint8_t* rgba = malloc((*w) * (*h) * 4);
    for (int i = 0; i < (*w) * (*h); i++) {
        rgba[i * 4 + 0] = rgb[i * 3 + 0];
        rgba[i * 4 + 1] = rgb[i * 3 + 1];
        rgba[i * 4 + 2] = rgb[i * 3 + 2];
        rgba[i * 4 + 3] = 255;
    }
    free(rgb);
    return rgba;
}

// Encode JPEG
uint8_t* encode_jpeg(const uint8_t* rgba, int w, int h, int quality, int progressive, const char* subsampling, size_t* out_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    memset(&cinfo, 0, sizeof(cinfo));
    cinfo.err = jpeg_std_error(&jerr);

    jpeg_CreateCompress(&cinfo, 80, sizeof(cinfo));

    uint8_t* out_buf = NULL;
    unsigned long out_len = 0;
    jpeg_mem_dest(&cinfo, &out_buf, &out_len);

    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = 2; // JCS_RGB

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, 1);

    if (subsampling && strcmp(subsampling, "4:4:4") == 0) {
        cinfo.comp_info[0].h_samp_factor = 1;
        cinfo.comp_info[0].v_samp_factor = 1;
        cinfo.comp_info[1].h_samp_factor = 1;
        cinfo.comp_info[1].v_samp_factor = 1;
        cinfo.comp_info[2].h_samp_factor = 1;
        cinfo.comp_info[2].v_samp_factor = 1;
    } else if (subsampling && strcmp(subsampling, "4:2:2") == 0) {
        cinfo.comp_info[0].h_samp_factor = 2;
        cinfo.comp_info[0].v_samp_factor = 1;
        cinfo.comp_info[1].h_samp_factor = 1;
        cinfo.comp_info[1].v_samp_factor = 1;
        cinfo.comp_info[2].h_samp_factor = 1;
        cinfo.comp_info[2].v_samp_factor = 1;
    } else if (subsampling && strcmp(subsampling, "4:2:0") == 0) {
        cinfo.comp_info[0].h_samp_factor = 2;
        cinfo.comp_info[0].v_samp_factor = 2;
        cinfo.comp_info[1].h_samp_factor = 1;
        cinfo.comp_info[1].v_samp_factor = 1;
        cinfo.comp_info[2].h_samp_factor = 1;
        cinfo.comp_info[2].v_samp_factor = 1;
    } else if (subsampling && strcmp(subsampling, "4:1:1") == 0) {
        cinfo.comp_info[0].h_samp_factor = 4;
        cinfo.comp_info[0].v_samp_factor = 1;
        cinfo.comp_info[1].h_samp_factor = 1;
        cinfo.comp_info[1].v_samp_factor = 1;
        cinfo.comp_info[2].h_samp_factor = 1;
        cinfo.comp_info[2].v_samp_factor = 1;
    }

    if (progressive) {
        jpeg_simple_progression(&cinfo);
    }

    jpeg_start_compress(&cinfo, 1);

    uint8_t* rgb = malloc(w * h * 3);
    for (int i = 0; i < w * h; i++) {
        rgb[i * 3 + 0] = rgba[i * 4 + 0];
        rgb[i * 3 + 1] = rgba[i * 4 + 1];
        rgb[i * 3 + 2] = rgba[i * 4 + 2];
    }

    uint8_t* row_ptrs[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_ptrs[0] = rgb + cinfo.next_scanline * w * 3;
        jpeg_write_scanlines(&cinfo, row_ptrs, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    free(rgb);

    *out_size = out_len;
    return out_buf;
}

// Decode PNG
uint8_t* decode_png(const uint8_t* in_data, size_t in_size, int* w, int* h) {
    MemReader reader = {in_data, in_size, 0};
    png_structp png_ptr = png_create_read_struct("1.6.37", NULL, NULL, NULL);
    if (!png_ptr) return NULL;
    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        png_destroy_read_struct(&png_ptr, NULL, NULL);
        return NULL;
    }

    png_set_read_fn(png_ptr, &reader, user_read_fn);
    png_read_info(png_ptr, info_ptr);

    uint32_t width = png_get_image_width(png_ptr, info_ptr);
    uint32_t height = png_get_image_height(png_ptr, info_ptr);
    uint8_t color_type = png_get_color_type(png_ptr, info_ptr);
    uint8_t bit_depth = png_get_bit_depth(png_ptr, info_ptr);

    if (color_type == 3) png_set_palette_to_rgb(png_ptr); // PNG_COLOR_TYPE_PALETTE
    if (color_type == 0 && bit_depth < 8) png_set_expand_gray_1_2_4_to_8(png_ptr); // PNG_COLOR_TYPE_GRAY
    if (color_type == 0 || color_type == 4) png_set_gray_to_rgb(png_ptr);
    png_set_tRNS_to_alpha(png_ptr);
    if (color_type == 2 || color_type == 0 || color_type == 3) {
        png_set_filler(png_ptr, 0xFF, 1); // filler after RGB
    }

    png_read_update_info(png_ptr, info_ptr);

    *w = width;
    *h = height;

    uint8_t* rgba = malloc(width * height * 4);
    uint8_t** row_ptrs = malloc(sizeof(uint8_t*) * height);
    for (uint32_t i = 0; i < height; i++) {
        row_ptrs[i] = rgba + i * width * 4;
    }

    png_read_image(png_ptr, row_ptrs);

    free(row_ptrs);
    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
    return rgba;
}

// Encode PNG
uint8_t* encode_png(const uint8_t* rgba, int w, int h, int opt_level, int quality, size_t* out_size) {
    MemWriter writer = {NULL, 0, 0};
    png_structp png_ptr = png_create_write_struct("1.6.37", NULL, NULL, NULL);
    if (!png_ptr) return NULL;
    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        png_destroy_write_struct(&png_ptr, NULL);
        return NULL;
    }

    png_set_write_fn(png_ptr, &writer, user_write_fn, user_flush_fn);
    png_set_compression_level(png_ptr, opt_level);

    // PNG_COLOR_TYPE_RGBA = 6, PNG_COMPRESSION_TYPE_BASE = 0, PNG_FILTER_TYPE_BASE = 0, PNG_INTERLACE_NONE = 0
    png_set_IHDR(png_ptr, info_ptr, w, h, 8, 6, 0, 0, 0);
    png_write_info(png_ptr, info_ptr);

    uint8_t** row_ptrs = malloc(sizeof(uint8_t*) * h);
    for (int i = 0; i < h; i++) {
        row_ptrs[i] = (uint8_t*)rgba + i * w * 4;
    }

    png_write_image(png_ptr, row_ptrs);
    png_write_end(png_ptr, info_ptr);

    free(row_ptrs);
    png_destroy_write_struct(&png_ptr, &info_ptr);

    *out_size = writer.size;
    return writer.data;
}

// Encode TIFF
int encode_tiff(const char* filename, const uint8_t* rgba, int w, int h) {
    void* tif = TIFFOpen(filename, "w");
    if (!tif) return 0;

    TIFFSetField(tif, 256, w); // IMAGEWIDTH
    TIFFSetField(tif, 257, h); // IMAGELENGTH
    TIFFSetField(tif, 258, 8); // BITSPERSAMPLE
    TIFFSetField(tif, 259, 5); // COMPRESSION_LZW = 5, or COMPRESSION_NONE = 1
    TIFFSetField(tif, 262, 2); // PHOTOMETRIC_RGB = 2
    TIFFSetField(tif, 277, 4); // SAMPLESPERPIXEL = 4
    TIFFSetField(tif, 284, 1); // PLANARCONFIG_CONTIG = 1

    for (int y = 0; y < h; y++) {
        TIFFWriteScanline(tif, (void*)(rgba + y * w * 4), y, 0);
    }

    TIFFClose(tif);
    return 1;
}

