static void user_read_fn(png_structp png_ptr, uint8_t* out_bytes, size_t length) {
    MemReader* r = (MemReader*)png_get_io_ptr(png_ptr);
    if (r->offset + length <= r->size) {
        memcpy(out_bytes, r->data + r->offset, length);
        r->offset += length;
    }
}

typedef struct {
    uint8_t* data;
    size_t size;
    size_t cap;
} MemWriter;

static void user_write_fn(png_structp png_ptr, uint8_t* in_bytes, size_t length) {
    MemWriter* w = (MemWriter*)png_get_io_ptr(png_ptr);
    if (w->size + length > w->cap) {
        w->cap = (w->size + length) * 2 + 1024;
        w->data = realloc(w->data, w->cap);
    }
    memcpy(w->data + w->size, in_bytes, length);
    w->size += length;
}

static void user_flush_fn(png_structp png_ptr) {}

// Resizing helper
uint8_t* resize_image(const uint8_t* src, int src_w, int src_h, int dst_w, int dst_h) {
    if (src_w == dst_w && src_h == dst_h) {
        uint8_t* dst = malloc(src_w * src_h * 4);
        memcpy(dst, src, src_w * src_h * 4);
        return dst;
    }
    uint8_t* dst = malloc(dst_w * dst_h * 4);
    for (int y = 0; y < dst_h; y++) {
        float src_y = (y + 0.5f) * src_h / (float)dst_h - 0.5f;
        if (src_y < 0) src_y = 0;
        int y0 = (int)src_y;
        int y1 = y0 + 1;
        if (y1 >= src_h) y1 = src_h - 1;
        float dy = src_y - y0;

        for (int x = 0; x < dst_w; x++) {
            float src_x = (x + 0.5f) * src_w / (float)dst_w - 0.5f;
            if (src_x < 0) src_x = 0;
            int x0 = (int)src_x;
            int x1 = x0 + 1;
            if (x1 >= src_w) x1 = src_w - 1;
            float dx = src_x - x0;

            for (int c = 0; c < 4; c++) {
                float p00 = src[(y0 * src_w + x0) * 4 + c];
                float p10 = src[(y0 * src_w + x1) * 4 + c];
                float p01 = src[(y1 * src_w + x0) * 4 + c];
                float p11 = src[(y1 * src_w + x1) * 4 + c];

                float val = p00 * (1 - dx) * (1 - dy) + p10 * dx * (1 - dy) + p01 * (1 - dx) * dy + p11 * dx * dy;
                dst[(y * dst_w + x) * 4 + c] = (uint8_t)(val < 0 ? 0 : (val > 255 ? 255 : val + 0.5f));
            }
        }
    }
    return dst;
}

