            return int(float(s[:-3]) * 1024 * 1024 * 1024)
        elif s.endswith('GB') or s.endswith('G'):
            suffix = 'GB' if s.endswith('GB') else 'G'
            return int(float(s[:-len(suffix)]) * 1000 * 1000 * 1000)
        elif s.endswith('B'):
            return int(float(s[:-1]))
        else:
            return int(float(s))
    except Exception:
        raise ValueError(f'Invalid size format: couldn\'t parse "{val_str}" into a ByteSize, cannot parse float from empty string')

