          Chroma subsampling for JPEG files [default: auto] [possible values: 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto]
      --jpeg-baseline
          Output baseline JPEG instead of progressive (default)
      --zopfli
          Use zopfli for PNG optimization (significantly slower but better compression)
  -e, --exif
          Keep EXIF metadata during compression
      --keep-dates
          Preserve original file timestamps
      --strip-icc
          Strips ICC profile info on JPG files, ignoring the -e flag
      --suffix <SUFFIX>
          Add suffix to output filenames
  -R, --recursive
          Scan subfolders recursively when input is a directory
  -S, --keep-structure
          Preserve directory structure (requires -R/--recursive)
  -d, --dry-run
          Simulate compression without writing files
      --threads <THREADS>
          Number of parallel jobs (0 = auto-detect, max = available processors) [default: 0]
  -O, --overwrite <OVERWRITE>
          Policy for handling existing output files [default: all] [possible values: all, never, bigger]
      --min-savings <MIN_SAVINGS>
          Minimum compression savings required to write an output file. Use percentage (e.g., '10%', '1.5%'), absolute size (e.g., '100KB', '1MB'), or plain number as bytes
  -Q, --quiet
          Suppress all output
      --verbose <VERBOSE>
          Verbosity level: 0 = quiet, 1 = progress only, 2 = errors only, 3 = all [default: 1]
  -h, --help
          Print help (see a summary with '-h')
  -V, --version
          Print version"""

def format_bytes(size):
    if size < 1024:
        return f"{size} B"
    units = ['KiB', 'MiB', 'GiB', 'TiB']
    val = float(size)
    for u in units:
        val /= 1024.0
        if val < 1024.0 or u == units[-1]:
            return f"{val:.1f} {u}"

def parse_size_bytes(val_str):
    s = val_str.strip().upper()
    try:
        if s.endswith('KIB'):
            return int(float(s[:-3]) * 1024)
        elif s.endswith('KB') or s.endswith('K'):
            suffix = 'KB' if s.endswith('KB') else 'K'
            return int(float(s[:-len(suffix)]) * 1000)
        elif s.endswith('MIB'):
            return int(float(s[:-3]) * 1024 * 1024)
        elif s.endswith('MB') or s.endswith('M'):
            suffix = 'MB' if s.endswith('MB') else 'M'
            return int(float(s[:-len(suffix)]) * 1000 * 1000)
        elif s.endswith('GIB'):
            return int(float(s[:-3]) * 1024 * 1024 * 1024)
        elif s.endswith('GB') or s.endswith('G'):
            suffix = 'GB' if s.endswith('GB') else 'G'
            return int(float(s[:-len(suffix)]) * 1000 * 1000 * 1000)
        elif s.endswith('B'):
            return int(float(s[:-1]))
        else:
            return int(float(s))
    except Exception:
        raise ValueError(f'Invalid size format: couldn\'t parse "{val_str}" into a ByteSize, cannot parse float from empty string')

# Load C library
lib_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'libimg.so')
libimg = ctypes.CDLL(lib_path)

