libimg.encode_webp.restype = ctypes.POINTER(ctypes.c_uint8)
libimg.encode_webp.argtypes = [ctypes.POINTER(ctypes.c_uint8), ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_size_t)]

libimg.decode_jpeg.restype = ctypes.POINTER(ctypes.c_uint8)
libimg.decode_jpeg.argtypes = [ctypes.POINTER(ctypes.c_uint8), ctypes.c_size_t, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]

libimg.encode_jpeg.restype = ctypes.POINTER(ctypes.c_uint8)
libimg.encode_jpeg.argtypes = [ctypes.POINTER(ctypes.c_uint8), ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_char_p, ctypes.POINTER(ctypes.c_size_t)]

libimg.decode_png.restype = ctypes.POINTER(ctypes.c_uint8)
libimg.decode_png.argtypes = [ctypes.POINTER(ctypes.c_uint8), ctypes.c_size_t, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]

libimg.encode_png.restype = ctypes.POINTER(ctypes.c_uint8)
libimg.encode_png.argtypes = [ctypes.POINTER(ctypes.c_uint8), ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_size_t)]

libimg.encode_tiff.restype = ctypes.c_int
libimg.encode_tiff.argtypes = [ctypes.c_char_p, ctypes.POINTER(ctypes.c_uint8), ctypes.c_int, ctypes.c_int]

