def main():
    args = sys.argv[1:]

    if '-V' in args or '--version' in args:
        print("caesiumclt 1.3.0")
        sys.exit(0)

    if '-h' in args or '--help' in args:
        print(HELP_TEXT)
        sys.exit(0)

    # Simple Arg Parser
    quality = None
    lossless = False
    max_size = None
    output_dir = None
    same_folder = False
    fmt = "original"
    suffix = ""
    recursive = False
    keep_structure = False
    dry_run = False
    threads = 0
    overwrite = "all"
    min_savings = None
    quiet = False
    verbose = 1
    exif = False
    keep_dates = False
    strip_icc = False
    png_opt_level = 3
    jpeg_subsampling = "auto"
    jpeg_baseline = False
    zopfli = False
    width = None
    height = None
    long_edge = None
    short_edge = None
    no_upscale = False

    files = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-q', '--quality'):
            if i + 1 >= len(args): sys.exit(2)
            try:
                quality = int(args[i+1])
            except ValueError:
                sys.exit(2)
            if quality < 0 or quality > 100:
                sys.stderr.write(f"error: invalid value '{args[i+1]}' for '--quality <QUALITY>': Quality must be between 0 and 100, but got {quality}\n\nFor more information, try '--help'.\n")
                sys.exit(2)
            i += 2
        elif arg == '--lossless':
            lossless = True
            i += 1
        elif arg == '--max-size':
            if i + 1 >= len(args): sys.exit(2)
            try:
                max_size = parse_size_bytes(args[i+1])
            except ValueError as e:
                sys.stderr.write(f"error: invalid value '{args[i+1]}' for '--max-size <MAX_SIZE>': {e}\n\nFor more information, try '--help'.\n")
                sys.exit(2)
            i += 2
        elif arg in ('-o', '--output'):
            if i + 1 >= len(args): sys.exit(2)
            output_dir = args[i+1]
            i += 2
        elif arg == '--same-folder-as-input':
            same_folder = True
            i += 1
        elif arg == '--format':
            if i + 1 >= len(args): sys.exit(2)
            fmt = args[i+1].lower()
            if fmt not in ('jpeg', 'png', 'gif', 'webp', 'tiff', 'original'):
                sys.exit(2)
            i += 2
        elif arg == '--suffix':
            if i + 1 >= len(args): sys.exit(2)
            suffix = args[i+1]
            i += 2
        elif arg in ('-R', '--recursive'):
            recursive = True
            i += 1
        elif arg in ('-S', '--keep-structure'):
            keep_structure = True
            i += 1
        elif arg in ('-d', '--dry-run'):
            dry_run = True
            i += 1
        elif arg == '--threads':
            if i + 1 >= len(args): sys.exit(2)
            try:
                threads = int(args[i+1])
            except ValueError:
                sys.stderr.write(f"error: invalid value '{args[i+1]}' for '--threads <THREADS>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                sys.exit(2)
            i += 2
        elif arg in ('-O', '--overwrite'):
            if i + 1 >= len(args): sys.exit(2)
            overwrite = args[i+1].lower()
            if overwrite not in ('all', 'never', 'bigger'):
                sys.exit(2)
            i += 2
        elif arg == '--min-savings':
            if i + 1 >= len(args): sys.exit(2)
            min_savings = args[i+1]
            i += 2
        elif arg in ('-Q', '--quiet'):
            quiet = True
            i += 1
        elif arg == '--verbose':
            if i + 1 >= len(args): sys.exit(2)
            try:
                verbose = int(args[i+1])
            except ValueError:
                sys.exit(2)
            i += 2
        elif arg in ('-e', '--exif'):
            exif = True
            i += 1
        elif arg == '--keep-dates':
            keep_dates = True
            i += 1
        elif arg == '--strip-icc':
            strip_icc = True
            i += 1
        elif arg == '--png-opt-level':
            if i + 1 >= len(args): sys.exit(2)
            try:
                png_opt_level = int(args[i+1])
            except ValueError:
                sys.exit(2)
            if png_opt_level < 0 or png_opt_level > 6:
                sys.stderr.write(f"error: invalid value '{args[i+1]}' for '--png-opt-level <PNG_OPT_LEVEL>': PNG optimization level must be between 0 and 6, but got {png_opt_level}\n\nFor more information, try '--help'.\n")
                sys.exit(2)
            i += 2
        elif arg == '--jpeg-chroma-subsampling':
            if i + 1 >= len(args): sys.exit(2)
            jpeg_subsampling = args[i+1]
            if jpeg_subsampling not in ('4:4:4', '4:2:2', '4:2:0', '4:1:1', 'auto'):
                sys.stderr.write(f"error: invalid value '{jpeg_subsampling}' for '--jpeg-chroma-subsampling <JPEG_CHROMA_SUBSAMPLING>'\n  [possible values: 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto]\n\nFor more information, try '--help'.\n")
                sys.exit(2)
            i += 2
        elif arg == '--jpeg-baseline':
            jpeg_baseline = True
            i += 1
        elif arg == '--zopfli':
            zopfli = True
            i += 1
        elif arg == '--width':
            if i + 1 >= len(args): sys.exit(2)
            width = int(args[i+1])
            i += 2
        elif arg == '--height':
            if i + 1 >= len(args): sys.exit(2)
            height = int(args[i+1])
            i += 2
        elif arg == '--long-edge':
            if i + 1 >= len(args): sys.exit(2)
            long_edge = int(args[i+1])
            i += 2
        elif arg == '--short-edge':
            if i + 1 >= len(args): sys.exit(2)
            short_edge = int(args[i+1])
            i += 2
        elif arg == '--no-upscale':
            no_upscale = True
            i += 1
        elif arg.startswith('-'):
            sys.exit(2)
        else:
            files.append(arg)
            i += 1

    # Conflict checks
    if quiet and ('--verbose' in args):
        sys.stderr.write("error: the argument '--quiet' cannot be used with '--verbose <VERBOSE>'\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    if quiet:
        verbose = 0

    mode_cnt = sum([quality is not None, lossless, max_size is not None])
    if mode_cnt != 1:
        if quality is not None and lossless:
            sys.stderr.write("error: the argument '--quality <QUALITY>' cannot be used with '--lossless'\n\nFor more information, try '--help'.\n")
        elif quality is not None and max_size is not None:
            sys.stderr.write("error: the argument '--quality <QUALITY>' cannot be used with '--max-size <MAX_SIZE>'\n\nFor more information, try '--help'.\n")
        elif lossless and max_size is not None:
            sys.stderr.write("error: the argument '--lossless' cannot be used with '--max-size <MAX_SIZE>'\n\nFor more information, try '--help'.\n")
        else:
            sys.stderr.write("error: the following required arguments were not provided:\n  <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>\n\nUsage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\nFor more information, try '--help'.\n")
        sys.exit(2)

    dest_cnt = sum([output_dir is not None, same_folder])
    if dest_cnt != 1:
        if output_dir is not None and same_folder:
            sys.stderr.write("error: the argument '--output <OUTPUT>' cannot be used with '--same-folder-as-input'\n\nFor more information, try '--help'.\n")
        else:
            sys.stderr.write("error: the following required arguments were not provided:\n  <--output <OUTPUT>|--same-folder-as-input>\n\nUsage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\nFor more information, try '--help'.\n")
        sys.exit(2)

    if (width is not None or height is not None) and (long_edge is not None or short_edge is not None):
        if width is not None and long_edge is not None:
            sys.stderr.write("error: the argument '--width <WIDTH>' cannot be used with '--long-edge <LONG_EDGE>'\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    if long_edge is not None and short_edge is not None:
        sys.stderr.write("error: the argument '--long-edge <LONG_EDGE>' cannot be used with '--short-edge <SHORT_EDGE>'\n\nFor more information, try '--help'.\n")
        sys.exit(2)

    if not files:
        sys.stderr.write("No files to compress\n")
        sys.exit(0)

    # File Collection & Extension filtering
    SUPPORTED_EXTS = {'.jpg', '.jpeg', '.png', '.webp', '.gif'}
    input_files = []

    for f_item in files:
        p = pathlib.Path(f_item)
        if p.is_file():
            if p.suffix.lower() in SUPPORTED_EXTS:
                input_files.append(p)
        elif p.is_dir():
            if recursive:
                for root, dirs, f_names in os.walk(p):
                    for fn in f_names:
                        fp = pathlib.Path(root) / fn
                        if fp.suffix.lower() in SUPPORTED_EXTS:
                            input_files.append(fp)
            else:
                for fn in os.listdir(p):
                    fp = p / fn
                    if fp.is_file() and fp.suffix.lower() in SUPPORTED_EXTS:
                        input_files.append(fp)

    if not input_files:
        sys.stderr.write("Unable to compute the base path for the files.\n")
        sys.exit(255)

    # Determine Base Path
    if len(files) == 1 and pathlib.Path(files[0]).is_dir():
        base_path = pathlib.Path(files[0])
    else:
        # Common parent of input files
        if len(input_files) == 1:
            base_path = input_files[0].parent
        else:
            parents_list = [p.resolve().parents for p in input_files]
            common = parents_list[0]
            for pl in parents_list[1:]:
                common = [p for p in common if p in pl]
            base_path = common[0] if common else input_files[0].parent

    # Parse Min Savings
    min_savings_pct = None
    min_savings_bytes = None
    if min_savings:
        ms = min_savings.strip()
        if ms.endswith('%'):
            try:
                min_savings_pct = float(ms[:-1])
            except ValueError:
                sys.stderr.write(f"error: invalid value '{min_savings}' for '--min-savings <MIN_SAVINGS>': Invalid size format: '{min_savings}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes\n\nFor more information, try '--help'.\n")
                sys.exit(2)
        else:
            try:
                min_savings_bytes = parse_size_bytes(ms)
            except Exception:
                sys.stderr.write(f"error: invalid value '{min_savings}' for '--min-savings <MIN_SAVINGS>': Invalid size format: '{min_savings}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes\n\nFor more information, try '--help'.\n")
                sys.exit(2)

    # Process files
    results = []

    def process_file(src_path):
        orig_size = src_path.stat().st_size
        ext_lower = src_path.suffix.lower()

        # Target extension
        if fmt == "original":
            target_ext = src_path.suffix
            target_fmt = ext_lower[1:]
            if target_fmt == 'jpeg': target_fmt = 'jpg'
        else:
            target_fmt = fmt
            target_ext = '.' + ('jpg' if fmt == 'jpeg' else fmt)

        # Output path
        if same_folder:
            out_dir = src_path.parent
        else:
            out_base = pathlib.Path(output_dir)
            if keep_structure:
                try:
                    rel = src_path.relative_to(base_path)
                    out_dir = out_base / rel.parent
                except ValueError:
                    out_dir = out_base
            else:
                out_dir = out_base

        stem = src_path.stem + suffix
        dst_path = out_dir / (stem + target_ext)

        # Format same check
        if fmt != "original":
            src_fmt = ext_lower[1:]
            if src_fmt in ('jpeg', 'jpg') and target_fmt in ('jpeg', 'jpg'):
                return ("error", src_path, dst_path, orig_size, 0, "Error compressing file: Cannot convert to the same format [10407]")
            if src_fmt == target_fmt:
                return ("error", src_path, dst_path, orig_size, 0, "Error compressing file: Cannot convert to the same format [10407]")

        # Read src data
        try:
            with open(src_path, 'rb') as f:
                data = f.read()
        except Exception as e:
            return ("error", src_path, dst_path, orig_size, 0, f"Error reading file: {e}")

        # Decode RGBA
        cdata = (ctypes.c_uint8 * len(data)).from_buffer_copy(data)
        w_in, h_in = ctypes.c_int(), ctypes.c_int()

        if ext_lower in ('.jpg', '.jpeg'):
            rgba_ptr = libimg.decode_jpeg(cdata, len(data), ctypes.byref(w_in), ctypes.byref(h_in))
        elif ext_lower == '.png':
            rgba_ptr = libimg.decode_png(cdata, len(data), ctypes.byref(w_in), ctypes.byref(h_in))
        elif ext_lower == '.webp':
            rgba_ptr = libimg.decode_webp(cdata, len(data), ctypes.byref(w_in), ctypes.byref(h_in))
        elif ext_lower == '.gif':
            # Handle GIF re-encoding
            rgba_ptr = libimg.decode_webp(cdata, len(data), ctypes.byref(w_in), ctypes.byref(h_in))
        else:
            return ("error", src_path, dst_path, orig_size, 0, "Unsupported file format")

        if not rgba_ptr or w_in.value == 0 or h_in.value == 0:
            return ("error", src_path, dst_path, orig_size, 0, "Error decoding image")

        w, h = w_in.value, h_in.value

        # Calculate resizing
        dst_w, dst_h = w, h
        if width is not None or height is not None:
            if width is not None and height is not None:
                dst_w, dst_h = width, height
            elif width is not None:
                dst_w = width
                dst_h = int(round(h * width / w))
            else:
                dst_h = height
                dst_w = int(round(w * height / h))
        elif long_edge is not None:
            if w >= h:
                dst_w = long_edge
                dst_h = int(round(h * long_edge / w))
            else:
                dst_h = long_edge
                dst_w = int(round(w * long_edge / h))
        elif short_edge is not None:
            if w <= h:
                dst_w = short_edge
                dst_h = int(round(h * short_edge / w))
            else:
                dst_h = short_edge
                dst_w = int(round(w * short_edge / h))

        if no_upscale and (dst_w > w or dst_h > h):
            dst_w, dst_h = w, h

        if dst_w != w or dst_h != h:
            resized_ptr = libimg.resize_image(rgba_ptr, w, h, dst_w, dst_h)
            rgba_ptr = resized_ptr
            w, h = dst_w, dst_h

        # Encode
        q_val = quality if quality is not None else 80
        out_len = ctypes.c_size_t()

        if target_fmt in ('jpg', 'jpeg'):
            enc_ptr = libimg.encode_jpeg(rgba_ptr, w, h, q_val, 0 if jpeg_baseline else 1, jpeg_subsampling.encode('utf-8'), ctypes.byref(out_len))
        elif target_fmt == 'png':
            enc_ptr = libimg.encode_png(rgba_ptr, w, h, png_opt_level, q_val, ctypes.byref(out_len))
        elif target_fmt == 'webp':
            enc_ptr = libimg.encode_webp(rgba_ptr, w, h, q_val, 1 if lossless else 0, ctypes.byref(out_len))
        elif target_fmt == 'tiff':
            # Handled via file write
            enc_ptr = None
        else:
            enc_ptr = None

        if target_fmt == 'tiff':
            out_bytes = None
            new_size = orig_size
        else:
            if not enc_ptr or out_len.value == 0:
                return ("error", src_path, dst_path, orig_size, 0, "Error encoding image")
            out_bytes = bytes(ctypes.cast(enc_ptr, ctypes.POINTER(ctypes.c_uint8 * out_len.value)).contents)
            new_size = len(out_bytes)

        # Overwrite Policy Check
        if dst_path.exists():
            if overwrite == "never":
                return ("skipped", src_path, dst_path, orig_size, orig_size, "File already exists, skipped due overwrite policy")
            elif overwrite == "bigger":
                if dst_path.stat().st_size <= new_size:
                    return ("skipped", src_path, dst_path, orig_size, orig_size, "File already exists, skipped due overwrite policy")

        # Min Savings Check
        savings = orig_size - new_size
        if min_savings_pct is not None:
            savings_pct = (savings / orig_size) * 100.0 if orig_size > 0 else 0.0
            if savings_pct < min_savings_pct:
                return ("skipped", src_path, dst_path, orig_size, orig_size, f"Insufficient savings: {savings_pct:.2f}% < {min_savings_pct:.2f}%, skipped")
        elif min_savings_bytes is not None:
            if savings < min_savings_bytes:
                return ("skipped", src_path, dst_path, orig_size, orig_size, f"Insufficient savings: {format_bytes(savings)} < {format_bytes(min_savings_bytes)}, skipped")

        # Dry Run
        if dry_run:
            return ("success", src_path, dst_path, orig_size, orig_size, "")

        # Write output file
        try:
            out_dir.mkdir(parents=True, exist_ok=True)
            if target_fmt == 'tiff':
                libimg.encode_tiff(str(dst_path).encode('utf-8'), rgba_ptr, w, h)
                new_size = dst_path.stat().st_size
            else:
                with open(dst_path, 'wb') as f:
                    f.write(out_bytes)

            if keep_dates:
                st = src_path.stat()
                os.utime(dst_path, (st.st_atime, st.st_mtime))

            return ("success", src_path, dst_path, orig_size, new_size, "")
        except Exception:
            return ("error", src_path, dst_path, orig_size, 0, "Error setting up output path")

    max_workers = threads if threads > 0 else (os.cpu_count() or 1)
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        results = list(executor.map(process_file, input_files))

    # Summary Statistics
    total_files = len(results)
    success_cnt = sum(1 for r in results if r[0] == "success")
    skipped_cnt = sum(1 for r in results if r[0] == "skipped")
    error_cnt = sum(1 for r in results if r[0] == "error")

    total_orig = sum(r[3] for r in results)
    total_new = sum(r[4] if r[0] == "success" else r[3] for r in results)

    # Verbose Output Formatting
    if verbose >= 2:
        for r in results:
            status, src_p, dst_p, orig_s, new_s, msg = r
            if status == "success" and verbose >= 3:
                diff = new_s - orig_s
                pct = (abs(diff) / orig_s) * 100.0 if orig_s > 0 else 0.0
                sign = '+' if diff > 0 else '-'
                diff_str = f"{sign}{format_bytes(abs(diff))}" if diff != 0 else "-0 B"
                pct_str = f"{sign}{pct:.2f}%" if diff != 0 else "-0.00%"
                print(f"[Success] {src_p} -> {dst_p}\n{format_bytes(orig_s)} -> {format_bytes(new_s)} [{diff_str} | {pct_str}]\n")
            elif status == "skipped":
                print(f"[Skipped] {src_p} -> {dst_p}\n{format_bytes(orig_s)} -> {format_bytes(orig_s)} [-0 B | -0.00%]\n{msg}\n")
            elif status == "error":
                out_dst_str = str(dst_p) if msg != "Error setting up output path" else ""
                print(f"[Error] {src_p} -> {out_dst_str}\n{format_bytes(orig_s)} -> 0 B [-{format_bytes(orig_s)} | -100.00%]\n{msg}\n")

    if verbose >= 1:
        total_diff = total_new - total_orig
        total_pct = (abs(total_diff) / total_orig) * 100.0 if total_orig > 0 else 0.0
        sign = '+' if total_diff > 0 else '-'
        diff_str = f"{sign}{format_bytes(abs(total_diff))}" if total_diff != 0 else "-0 B"
        pct_str = f"{sign}{total_pct:.2f}%" if total_diff != 0 else "-0.00%"

        print(f"Compressed {total_files} files ({success_cnt} success, {skipped_cnt} skipped, {error_cnt} errors)")
        print(f"{format_bytes(total_orig)} -> {format_bytes(total_new)} [{diff_str} | {pct_str}]")

if __name__ == '__main__':
    main()
