    void (*format_message)(void* cinfo, char* buffer);
    void (*reset_error_mgr)(void* cinfo);
    int trace_level;
    long num_warnings;
    const char* const* jpeg_message_table;
    int last_jpeg_message;
    const char* const* addon_message_table;
    int first_addon_message;
    int last_addon_message;
};

struct jpeg_decompress_struct {
    struct jpeg_error_mgr* err;
    uint8_t padding[648];
};

struct jpeg_compress_struct {
    struct jpeg_error_mgr* err;
    uint8_t padding[576];
};

extern void* jpeg_std_error(void* err);
extern void jpeg_CreateDecompress(void* cinfo, int version, size_t struct_size);
extern void jpeg_CreateCompress(void* cinfo, int version, size_t struct_size);
extern void jpeg_destroy_decompress(void* cinfo);
extern void jpeg_destroy_compress(void* cinfo);
extern void jpeg_mem_src(void* cinfo, const uint8_t* inbuffer, unsigned long insize);
extern void jpeg_mem_dest(void* cinfo, uint8_t** outbuffer, unsigned long* outsize);
extern int jpeg_read_header(void* cinfo, int require_image);
extern int jpeg_start_decompress(void* cinfo);
extern uint32_t jpeg_read_scanlines(void* cinfo, uint8_t** scanlines, uint32_t max_lines);
extern int jpeg_finish_decompress(void* cinfo);

extern void jpeg_set_defaults(void* cinfo);
extern void jpeg_set_quality(void* cinfo, int quality, int force_baseline);
extern void jpeg_simple_progression(void* cinfo);
extern void jpeg_start_compress(void* cinfo, int write_all_tables);
extern uint32_t jpeg_write_scanlines(void* cinfo, uint8_t** scanlines, uint32_t num_lines);
extern void jpeg_finish_compress(void* cinfo);

int main() {
    FILE* f = fopen("assets/j0.JPG", "rb");
    fseek(f, 0, SEEK_END);
    size_t len = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* buf = malloc(len);
    fread(buf, 1, len, f);
    fclose(f);

    struct jpeg_decompress_struct dinfo;
    uint8_t err[200];
    memset(&dinfo, 0, sizeof(dinfo));
    memset(err, 0, sizeof(err));
    dinfo.err = jpeg_std_error(err);

    jpeg_CreateDecompress(&dinfo, 80, 656);
    jpeg_mem_src(&dinfo, buf, len);
    jpeg_read_header(&dinfo, 1);

    *(int*)((uint8_t*)&dinfo + 68) = 2; // JCS_RGB
    jpeg_start_decompress(&dinfo);

    uint32_t w = *(uint32_t*)((uint8_t*)&dinfo + 136);
    uint32_t h = *(uint32_t*)((uint8_t*)&dinfo + 140);
    uint8_t* rgb = malloc(w * h * 3);
    uint8_t* row_ptrs[1];

    while (*(uint32_t*)((uint8_t*)&dinfo + 168) < h) {
        row_ptrs[0] = rgb + (*(uint32_t*)((uint8_t*)&dinfo + 168)) * w * 3;
        jpeg_read_scanlines(&dinfo, row_ptrs, 1);
    }
    jpeg_finish_decompress(&dinfo);
    jpeg_destroy_decompress(&dinfo);

    struct jpeg_compress_struct cinfo;
    memset(&cinfo, 0, sizeof(cinfo));
    memset(err, 0, sizeof(err));
    cinfo.err = jpeg_std_error(err);

    jpeg_CreateCompress(&cinfo, 80, 584);
    uint8_t* out_buf = NULL;
    unsigned long out_len = 0;
    jpeg_mem_dest(&cinfo, &out_buf, &out_len);

    *(uint32_t*)((uint8_t*)&cinfo + 48) = w;
    *(uint32_t*)((uint8_t*)&cinfo + 52) = h;
    *(int*)((uint8_t*)&cinfo + 56) = 3;
    *(int*)((uint8_t*)&cinfo + 60) = 2; // JCS_RGB

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 80, 1);
    jpeg_simple_progression(&cinfo);
    jpeg_start_compress(&cinfo, 1);

    int scanline = 0;
    while (scanline < h) {
        row_ptrs[0] = rgb + scanline * w * 3;
        jpeg_write_scanlines(&cinfo, row_ptrs, 1);
        scanline++;
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    printf("JPEG size: %lu bytes (%.1f KiB)\n", out_len, out_len / 1024.0);

    FILE* out_f = fopen("/tmp/test_j0_out.jpg", "wb");
    fwrite(out_buf, 1, out_len, out_f);
    fclose(out_f);
    return 0;
}
